version.transform:
(
  $unitCodes := $;

  $units := [
    $query({
      "statement": '
        query ($code: [String!]!) {
          data: unit(
            where: {
              code: {
                _in: $code
              }
            }
          ) {
            edges {
              node {
                id
                code
              }
            }
          }
        }
      ',
      "variables": {
        "code": [$unitCodes]
      }
    }).data.edges.node
  ];

  $filteredUnits := [
    $filter($unitCodes,function($v){
      $not($lowercase($v) in [$units.($lowercase(code))])
    })
  ];

  $addOrUpdate := (
    $count($filteredUnits) = 0 ?
    (
      $units
    )
    :
    (
      $output := $mutate({
        "statement": '
          mutation ($payload: [UnitCreatePayloadInput!]!) {
            data: createUnit(payload: $payload) {
              id
              code
            }
          }
        ',
        "variables": {
          "payload": [
            $filteredUnits.{
              "create": {
                "code": $,
                "name": $,
                "unitTypeId": "Amount"
              }
            }
          ]
        }
      }).data;

      $output;
    )
  );

  $uniqBy([$addOrUpdate,$units],function($v){
    $v.id
  })
)
